// Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely.
import { useState, type FormEvent } from 'react'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/react'

import { Button } from '@@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@@/components/ui/dialog'
import { Input } from '@@/components/ui/input'
import { Label } from '@@/components/ui/label'
import { reportAuthError } from '@@/lib/auth'
import { formatRetryAfter, isAuthError, MFA_TEXTS } from '@@/lib/mfa'

// Global: the backend answered 403 `mfa_enrollment_required` on a regular request (the
// panel requires 2FA, the user has none). The gate never issues the setup link — the user
// confirms the password, then gets a full navigation to the auth server's /setup-2fa page.
// Not dismissable; the alternative is logging out. Rendered by <AuthMfaDialogs />.
export function MfaEnrollmentRequiredDialog() {
  const mfa = useMfa()
  const { logout, isAuthenticated } = useAuth()
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  const open = isAuthenticated && mfa.stage === 'enrollment' && mfa.enrollmentUrl === null

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!password || pending) return
    setError(null)
    setPending(true)
    try {
      const url = await mfa.requestEnrollment(password)
      window.location.assign(url)
    } catch (err) {
      setPending(false)
      if (isAuthError(err, 'InvalidCredentialsError')) {
        setError(MFA_TEXTS.invalidPassword)
      } else if (isAuthError(err, 'TooManyAttemptsError')) {
        setError(formatRetryAfter(err.retryAfter))
      } else if (isAuthError(err, 'MfaAlreadyEnabledError')) {
        setError(MFA_TEXTS.alreadyEnabled)
      } else {
        // Unexpected failure (5xx, network): short inline text + the global report.
        setError(MFA_TEXTS.enrollmentFailed)
        reportAuthError(err, MFA_TEXTS.enrollmentFailed)
      }
    }
  }

  const handleLogout = () => {
    setPassword('')
    setError(null)
    void logout().catch((err: unknown) => reportAuthError(err, MFA_TEXTS.logoutFailed))
  }

  return (
    <Dialog open={open}>
      <DialogContent
        showCloseButton={false}
        onEscapeKeyDown={(e) => e.preventDefault()}
        onInteractOutside={(e) => e.preventDefault()}
      >
        <DialogHeader>
          <DialogTitle>Ten panel wymaga 2FA</DialogTitle>
          <DialogDescription>
            Ten panel wymaga weryfikacji dwuetapowej (2FA). Potwierdź hasło, aby przejść do
            konfiguracji aplikacji uwierzytelniającej.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={(e) => void handleSubmit(e)} className="space-y-4" noValidate>
          <div className="space-y-2">
            <Label htmlFor="mfa-enrollment-password">Hasło</Label>
            <Input
              id="mfa-enrollment-password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoFocus
              disabled={pending}
              aria-invalid={error !== null}
            />
            {error ? <p className="text-sm text-destructive">{error}</p> : null}
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleLogout} disabled={pending}>
              Wyloguj się
            </Button>
            <Button type="submit" disabled={!password || pending}>
              {pending ? 'Przygotowywanie…' : 'Przejdź do konfiguracji'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}
